/**
 * Phone -> desktop photo relay.
 *
 * The runbooks page (desktop) opens a room and listens on a Server-Sent
 * Events stream. The phone page (opened from a QR code) POSTs photos to the
 * room; each photo is written straight into the desktop's open stream and
 * then dropped. Nothing is written to disk, nothing is kept in memory after
 * the forward, and a photo POSTed to a room with no listener is rejected
 * rather than queued.
 *
 * The photos arrive already encrypted (AES-GCM, key generated by the desktop
 * page and carried only in the QR link's #fragment, which browsers never
 * send to a server), so this relay only ever sees ciphertext.
 *
 * Routes (all under /relay):
 *   GET  /relay/<room>/events  desktop listener (SSE). One listener per room.
 *   POST /relay/<room>/hello   phone announces itself (JSON {device?})
 *   POST /relay/<room>/photo   phone sends one photo of a batch
 *                              (JSON {batch,index,count,name,type,iv,data})
 *
 * The phone sends a reviewed set of photos with "Send all": one POST per
 * photo, in order, tagged with a batch id, its 1-based index and the batch
 * size. The desktop page holds a batch until all `count` photos arrived.
 *
 * <room> is a random 128-bit id chosen by the desktop (base64url, 22 chars).
 */

const ROOM_RE = /^\/relay\/([A-Za-z0-9_-]{22,64})\/(events|hello|photo)$/;

const MAX_BODY_BYTES     = 12 * 1024 * 1024;  // one encrypted photo, base64 in JSON
const MAX_BATCH          = 50;                // photos per Send all
const BATCH_ID_RE        = /^[A-Za-z0-9_-]{8,40}$/;
const MAX_ROOMS          = 500;
const MAX_ROOMS_PER_IP   = 5;
const ROOM_MAX_AGE_MS    = 30 * 60 * 1000;    // a pairing lasts at most 30 min
const HEARTBEAT_MS       = 20 * 1000;         // keeps the reverse proxy from timing out
const POST_WINDOW_MS     = 10 * 60 * 1000;
const POSTS_PER_WINDOW   = 120;               // per phone IP

/** room id -> { res, ip, createdAt, timer, heartbeat } */
const rooms = new Map();
/** ip -> [timestamps] of recent POSTs */
const postLog = new Map();

function isPrivateAddr(addr) {
  const a = String(addr || '').replace(/^::ffff:/, '');
  return a === '::1' || /^127\./.test(a) || /^10\./.test(a) || /^192\.168\./.test(a)
    || /^172\.(1[6-9]|2\d|3[01])\./.test(a) || /^f[cd][0-9a-f]{2}:/i.test(a);
}

// Never the leftmost X-Forwarded-For entry: nginx appends to whatever the
// client sent, so that value is client-chosen. Trust X-Real-IP (our reverse proxy sets it to
// $remote_addr), else the rightmost hop, and only from our own proxy.
function clientIp(req) {
  const peer = String(req.socket.remoteAddress || '');
  if (!isPrivateAddr(peer)) return peer.replace(/^::ffff:/, '');
  const real = String(req.headers['x-real-ip'] || '').trim();
  if (real) return real;
  const hops = String(req.headers['x-forwarded-for'] || '').split(',').map(x => x.trim()).filter(Boolean);
  return hops.length ? hops[hops.length - 1] : peer.replace(/^::ffff:/, '');
}

function json(res, status, body, cors) {
  res.writeHead(status, { 'Content-Type': 'application/json', 'Cache-Control': 'no-store', ...cors });
  res.end(JSON.stringify(body));
}

function rateLimited(ip) {
  const now = Date.now();
  const log = (postLog.get(ip) || []).filter(t => now - t < POST_WINDOW_MS);
  log.push(now);
  postLog.set(ip, log);
  return log.length > POSTS_PER_WINDOW;
}

// Drop rate-limit entries that have aged out so the map can't grow forever.
setInterval(() => {
  const now = Date.now();
  for (const [ip, log] of postLog) {
    if (!log.some(t => now - t < POST_WINDOW_MS)) postLog.delete(ip);
  }
}, POST_WINDOW_MS).unref();

async function readLimited(req, limit) {
  const chunks = [];
  let size = 0;
  for await (const chunk of req) {
    size += chunk.length;
    if (size > limit) return null;
    chunks.push(chunk);
  }
  return Buffer.concat(chunks);
}

function send(room, event, data) {
  room.res.write(`event: ${event}\ndata: ${JSON.stringify(data)}\n\n`);
}

function closeRoom(id) {
  const room = rooms.get(id);
  if (!room) return;
  rooms.delete(id);
  clearTimeout(room.timer);
  clearInterval(room.heartbeat);
  try { room.res.end(); } catch { /* already closed */ }
}

function openRoom(id, req, res, cors) {
  const ip = clientIp(req);
  if (rooms.has(id)) return json(res, 409, { error: 'room-in-use', message: 'This room already has a listener.' }, cors);
  if (rooms.size >= MAX_ROOMS) return json(res, 503, { error: 'relay-busy', message: 'Too many open rooms; try again shortly.' }, cors);
  let perIp = 0;
  for (const r of rooms.values()) if (r.ip === ip) perIp++;
  if (perIp >= MAX_ROOMS_PER_IP) return json(res, 429, { error: 'too-many-rooms', message: 'Too many open rooms from this address.' }, cors);

  res.writeHead(200, {
    'Content-Type': 'text/event-stream',
    'Cache-Control': 'no-store',
    'Connection': 'keep-alive',
    'X-Accel-Buffering': 'no',   // tell nginx not to buffer the stream
    ...cors,
  });
  res.write(`retry: 3000\n\n`);
  const room = {
    res, ip, createdAt: Date.now(),
    timer: setTimeout(() => {
      send(room, 'expired', { message: 'Pairing expired.' });
      closeRoom(id);
    }, ROOM_MAX_AGE_MS),
    heartbeat: setInterval(() => res.write(`: ping\n\n`), HEARTBEAT_MS),
  };
  rooms.set(id, room);
  send(room, 'ready', { maxAgeMs: ROOM_MAX_AGE_MS });
  req.on('close', () => { if (rooms.get(id) === room) closeRoom(id); });
}

async function phonePost(id, kind, req, res, cors) {
  const ip = clientIp(req);
  if (rateLimited(ip)) return json(res, 429, { error: 'rate-limited', message: 'Too many uploads; wait a few minutes.' }, cors);
  const room = rooms.get(id);
  if (!room) {
    // Drain so the client sees the response instead of a reset.
    req.resume();
    return json(res, 404, { error: 'room-not-found', message: 'The runbook page is not listening. Rescan the QR code.' }, cors);
  }
  const body = await readLimited(req, MAX_BODY_BYTES);
  if (body === null) {
    // The rest of the upload was not read, so this connection can't be
    // reused for another request: close it after the response.
    return json(res, 413, { error: 'too-large', message: 'Photo is too large.' }, { ...cors, Connection: 'close' });
  }
  let msg;
  try { msg = JSON.parse(body.toString('utf8')); } catch {
    return json(res, 400, { error: 'bad-json', message: 'Body must be JSON.' }, cors);
  }

  if (kind === 'hello') {
    send(room, 'phone', { device: String(msg.device || '').slice(0, 120) });
    return json(res, 200, { ok: true }, cors);
  }

  const { batch, index, count, name, type, iv, data } = msg;
  if (typeof iv !== 'string' || typeof data !== 'string' || !data) {
    return json(res, 400, { error: 'bad-photo', message: 'Expected {batch, index, count, name, type, iv, data}.' }, cors);
  }
  if (!BATCH_ID_RE.test(String(batch || '')) || !Number.isInteger(index) || !Number.isInteger(count)
      || count < 1 || count > MAX_BATCH || index < 1 || index > count) {
    return json(res, 400, { error: 'bad-batch', message: `batch must be an id; 1 <= index <= count <= ${MAX_BATCH}.` }, cors);
  }
  // Re-check: the desktop may have gone away while the body was uploading.
  if (rooms.get(id) !== room) return json(res, 404, { error: 'room-not-found', message: 'The runbook page stopped listening.' }, cors);
  send(room, 'photo', {
    batch, index, count,
    name: String(name || 'photo.jpg').slice(0, 120),
    type: String(type || 'image/jpeg').slice(0, 60),
    iv, data,
  });
  // `msg` / `body` go out of scope here -- the relay keeps nothing.
  return json(res, 200, { ok: true }, cors);
}

/**
 * Handle a /relay request. Returns false if the path isn't a relay route so
 * the caller can fall through to its own handling.
 */
export function handleRelay(req, res, cors) {
  const path = new URL(req.url || '/', 'http://x').pathname;
  if (!path.startsWith('/relay/')) return false;
  const m = path.match(ROOM_RE);
  if (!m) { json(res, 404, { error: 'not-found', message: 'Unknown relay route.' }, cors); return true; }
  const [, id, kind] = m;
  if (kind === 'events') {
    if (req.method !== 'GET') { json(res, 405, { error: 'method-not-allowed', message: 'Use GET.' }, cors); return true; }
    openRoom(id, req, res, cors);
    return true;
  }
  if (req.method !== 'POST') { json(res, 405, { error: 'method-not-allowed', message: 'Use POST.' }, cors); return true; }
  phonePost(id, kind, req, res, cors).catch(err => {
    console.error('[relay] post error:', err.message);
    if (!res.headersSent) json(res, 500, { error: 'relay-error', message: err.message }, cors);
  });
  return true;
}

export function relayStats() {
  return { rooms: rooms.size };
}
